{
  "test_cases": [
    {
      "id": "TC-KDH-038-01",
      "title": "Disabling multiple authenticators after threshold exceeded",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with both a password and a second factor (e.g., OTP) bound. The failure threshold defined in VBP SDD §14 is known (assumed to be 5 for this test). The account is currently active.",
      "test_inputs": "Valid username, invalid password, invalid second factor code.",
      "assumptions": "The threshold for consecutive failed attempts defined in VBP SDD §14 is 5. The system tracks failures per authenticator and per account.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt authentication using the valid username, an invalid password, and a valid second factor code.",
          "expected": "Authentication fails. The system records a failed attempt for the password authenticator."
        },
        {
          "no": 2,
          "action": "Repeat the authentication attempt with the invalid password and valid second factor code until the threshold (5) is reached.",
          "expected": "After the 5th failed attempt, the system disables the password authenticator. The second factor remains active as it was not involved in the failure."
        },
        {
          "no": 3,
          "action": "Reset the failure count (e.g., via admin tool or time-based reset if applicable, or use a new session if the counter is per-session) and attempt authentication using the valid username, a valid password, and an invalid second factor code.",
          "expected": "Authentication fails. The system records a failed attempt for the second factor authenticator."
        },
        {
          "no": 4,
          "action": "Repeat the authentication attempt with the valid password and invalid second factor code until the threshold (5) is reached.",
          "expected": "After the 5th failed attempt, the system disables the second factor authenticator. The password remains active."
        },
        {
          "no": 5,
          "action": "Reset the failure count and attempt authentication using the valid username, an invalid password, and an invalid second factor code.",
          "expected": "Authentication fails. The system records a failed attempt for both authenticators."
        },
        {
          "no": 6,
          "action": "Repeat the authentication attempt with both invalid factors until the threshold (5) is reached.",
          "expected": "After the 5th failed attempt, the system disables both the password and the second factor authenticators, as specified in NIST SP 800-63B-4 §3.2.2."
        }
      ]
    },
    {
      "id": "TC-KDH-038-02",
      "title": "Verification that disabled authenticators require re-binding",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "A company representative account has both password and second factor disabled due to exceeding the failure threshold.",
      "test_inputs": "Valid username, valid password, valid second factor code.",
      "assumptions": "The re-binding process is available and documented in the system.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt authentication using the valid username, valid password, and valid second factor code.",
          "expected": "Authentication is rejected because the authenticators are disabled. The system prompts for re-binding or recovery."
        },
        {
          "no": 2,
          "action": "Initiate the re-binding process for the password authenticator.",
          "expected": "The password authenticator is re-bound to the account and becomes active."
        },
        {
          "no": 3,
          "action": "Initiate the re-binding process for the second factor authenticator.",
          "expected": "The second factor authenticator is re-bound to the account and becomes active."
        },
        {
          "no": 4,
          "action": "Attempt authentication using the valid username, valid password, and valid second factor code.",
          "expected": "Authentication succeeds. The account is fully functional again."
        }
      ]
    }
  ]
}

